bounded_host_request.command:
set -eu
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name" 2>/dev/null)" = true || { echo BOT_STOPPED; exit 81; }
test "$(docker logs --tail 200 "$name" 2>&1 | grep -c '^CREATOR_DM_POLL_READY=PASS$' || true)" -gt 0 || { echo DM_POLL_NOT_READY; exit 82; }
test "$(docker logs --tail 200 "$name" 2>&1 | grep -c '^CREATOR_GATE_PUBLIC_RELEASE=CONNECTED$' || true)" -gt 0 || { echo GATE_RELEASE_NOT_CONNECTED; exit 83; }
echo BOT_RESTORED_READY
